from pathlib import Path

p=Path('src/components/AdmissionsPlannerV11.tsx')
s=p.read_text()
s=s.replace("import WeeklyPlanExperience from '@/components/WeeklyPlanExperience';", "import WeeklyPlanExperience from '@/components/WeeklyPlanExperience';\nimport DifficultyProfile from '@/components/DifficultyProfile';\nimport { type DifficultySelection } from '@/lib/exam-skill-catalog';")
s=s.replace("  const[cutoffs,setCutoffs]=useState<AdmissionCutoff[]>([]);", "  const[cutoffs,setCutoffs]=useState<AdmissionCutoff[]>([]);\n  const[difficultyTopics,setDifficultyTopics]=useState<DifficultySelection>({});")
