needle="      {tab==='plano'&&<div className=\"plan6-grid\">\n        <section className=\"plan6-card span12\"><div className=\"plan6-sectionlabel\">Semana por semana</div>"
rep="      {tab==='plano'&&<div className=\"plan6-grid\">\n        <DifficultyProfile examId={model.examId} course={course} value={difficultyTopics} onChange={setDifficultyTopics}/>\n        <section className=\"plan6-card span12\"><div className=\"plan6-sectionlabel\">Semana por semana</div>"
s=s.replace(needle,rep)
